package com.alfa.device_ctrl;
import android.Manifest;import android.app.Activity;import android.app.NotificationChannel;import android.app.NotificationManager;import android.content.Intent;import android.content.pm.PackageManager;import android.os.Build;import android.os.Bundle;import android.provider.Settings;import android.widget.Button;import android.widget.LinearLayout;import android.widget.TextView;
/** Real notification permission/channel state surface; no simulated PASS state. */
public final class NotificationStateActivity extends Activity{private TextView report;private static final int REQUEST_NOTIFICATIONS=9101;@Override protected void onCreate(Bundle s){super.onCreate(s);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(dp(14),dp(14),dp(14),dp(14));r.setBackgroundColor(android.graphics.Color.rgb(19,19,21));TextView t=new TextView(this);t.setText("NOTIFICATION / FGS STATE");t.setTextColor(android.graphics.Color.rgb(171,199,255));t.setTextSize(16);r.addView(t,new LinearLayout.LayoutParams(-1,dp(52)));report=new TextView(this);report.setTextColor(android.graphics.Color.rgb(193,198,213));report.setTextSize(11);report.setTypeface(android.graphics.Typeface.MONOSPACE);r.addView(report,new LinearLayout.LayoutParams(-1,0,1));Button req=new Button(this);req.setText("REQUEST POST_NOTIFICATIONS");req.setMinHeight(dp(48));req.setOnClickListener(v->requestNotificationPermission());r.addView(req);Button set=new Button(this);set.setText("OPEN SYSTEM NOTIFICATION SETTINGS");set.setMinHeight(dp(48));set.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName())));r.addView(set);setContentView(r);refresh();}@Override protected void onResume(){super.onResume();refresh();}private void requestNotificationPermission(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},REQUEST_NOTIFICATIONS);else refresh();}private void refresh(){NotificationManager m=getSystemService(NotificationManager.class);StringBuilder b=new StringBuilder();b.append("POST_NOTIFICATIONS=").append(Build.VERSION.SDK_INT<33||checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)==PackageManager.PERMISSION_GRANTED?"GRANTED":"DENIED").append('\n');b.append("APP_NOTIFICATIONS=").append(m.areNotificationsEnabled()?"ENABLED":"DISABLED").append('\n');NotificationChannel c=Build.VERSION.SDK_INT>=26?m.getNotificationChannel("alfa_runtime_session"):null;b.append("FGS_CHANNEL=").append(c==null?"NOT_CREATED":"PRESENT").append('\n');if(c!=null)b.append("FGS_CHANNEL_IMPORTANCE=").append(c.getImportance()).append('\n');b.append("FGS_SERVICE_ACTIVE=").append(RuntimeKeepAliveService.isActive()?"YES":"NO").append('\n');b.append("FGS_TYPE=specialUse\nTARGET_SDK=").append(getApplicationInfo().targetSdkVersion);report.setText(b.toString());}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}}
